    [2, 7, 0, 1],
    [7, 4, 1, 4]
]

def transform(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    out_h, out_w = h // 3, w // 3
    output = [[0] * out_w for _ in range(out_h)]

    for i in range(out_h):
        for j in range(out_w):
            block = []
            for r in range(3*i, 3*i+3):
                for c in range(3*j, 3*j+3):
                    block.append(input_grid[r][c])

            counts = {}
            for v in block:
                counts[v] = counts.get(v, 0) + 1

            sorted_items = sorted(counts.items(), key=lambda x: (-x[1], x[0]))

            if len(sorted_items) >= 2:
                output[i][j] = sorted_items[1][0]
            else:
                output[i][j] = sorted_items[0][0]  # Fallback to the only value

    return output

demo_result = transform(demo_input)
